function runKernel(name, ctx={}) {
    const fn=CATALOG[String(name)];
    if(typeof fn!=='function') throw new Error('Unknown kernel: '+name);
    const started=now();
    const result=fn(ctx);
    return {...safeObj(result), elapsedMs:now()-started};
}
function listKernels(prefix='') { return Object.keys(CATALOG).filter(k=>!prefix||k.startsWith(prefix)); }
function health() { return {kind:'dashboard', kernels:Object.keys(CATALOG).length, stateEntries:STATE.size, ts:now()}; }
module.exports={runKernel,listKernels,health,CATALOG};

// Runtime API registration: these endpoints expose the advanced engine without
// widening the existing Discord command surface. They reuse dashboard auth.
function registerDashboardEngine(app, deps) {
    const requireApi = deps.requireApi;
    const requireGuildAccess = deps.requireGuildAccess;
    const rateLimit = deps.rateLimit;
    const wrap = deps.wrap;
    const client = deps.client;
    const analytics = deps.analytics;
    app.get('/api/engine/health', requireApi, rateLimit(30, 60000), wrap((req, res) => {
        res.json({ok:true, runtime:health(), analytics:analytics.health(), ts:Date.now()});
    }));
    app.get('/api/engine/kernels', requireApi, rateLimit(30, 60000), wrap((req, res) => {
        const prefix=String(req.query?.prefix||'').slice(0,64);
        res.json({ok:true, kernels:listKernels(prefix).slice(0,500), total:Object.keys(CATALOG).length});
    }));
    app.get('/api/guilds/:guildId/dashboard/engine', requireApi, requireGuildAccess,
        rateLimit(30, 60000), wrap((req, res) => {
            const guild=client.guilds.cache.get(req.params.guildId);
            if (!guild) return res.status(404).json({error:'Server not found.'});
            const sample=runKernel('dashboard_kernel_0001', {
                id:guild.id,
                data:{members:guild.memberCount||0,channels:guild.channels.cache.size,roles:guild.roles.cache.size}
            });
            res.json({ok:true,guild:{id:guild.id,name:guild.name},widget:sample,engine:health()});
        }));
}



